begin;
-- Hydrate DANI-generic research programs only. ENTITY_ARCHITECTURE and project-specific
-- Shadow & Sol / Own Land research are intentionally excluded. All programs remain
-- RESEARCHING + release_blocked; this migration grants no commercialization authority.
on conflict(program_key) do update set
 program_name=excluded.program_name,domain=excluded.domain,objective=excluded.objective,status='RESEARCHING',
 release_blocked=true,green_rule=excluded.green_rule,
 metadata=coalesce(public.dd_research_programs.metadata,'{}'::jsonb)||excluded.metadata||jsonb_build_object('hydrated_for_production_research',true,'research_authority_only',true),
 updated_at=now();

-- Preserve existing production-only backfill and existing Protection & Benefits.
-- Explicit exclusion proof: this migration contains no ENTITY_ARCHITECTURE program key.
commit;
